Float r, theta;
if (u.x < u.y) {
    // First quadrant
    if (u.x + u.y > 1) {
        r = 1 - u.y;
        theta = PiOver2 * (1 - u.x) / u.y;
    } else {
        r = u.x + u.y;
        theta = PiOver2 * u.x / (1 - u.y);
    }
} else {
    // Second quadrant
    if (u.x + u.y > 1) {
        r = 1 - u.x;
        theta = PiOver2 * (2 - u.y) / u.x;
    } else {
        r = u.x + u.y;
        theta = PiOver2 * (2 - u.x) / u.y;
    }
}
return Point2f(std::cos(theta) * r, std::sin(theta) * r);

